import Foundation
import RustCoreFramework

/// Time-based One-Time Password (TOTP) codes, generated by the Rust core (`core/rust/src/totp`).
public class TotpGenerator {
    /// Generate a TOTP code from a secret key.
    /// - Parameters:
    ///   - secret: The Base32-encoded secret key
    ///   - time: The current time (defaults to now)
    ///   - period: The time step in seconds (defaults to 30)
    ///   - digits: Number of digits in the code (defaults to 6)
    ///   - algorithm: The HMAC algorithm name: SHA1, SHA256 or SHA512 (defaults to SHA1)
    /// - Returns: The generated TOTP code, or nil if the secret is unusable
    public static func generateCode(
        secret: String,
        time: Date = Date(),
        period: Int = 30,
        digits: Int = 6,
        algorithm: String = "SHA1"
    ) -> String? {
        return RustCoreFramework.generateTotpCode(
            secret: secret,
            unixSeconds: Int64(time.timeIntervalSince1970),
            algorithm: algorithm,
            digits: UInt32(clamping: digits),
            period: UInt32(clamping: period)
        )
    }

    /// Get the remaining seconds until the next TOTP code.
    /// - Parameters:
    ///   - time: The current time (defaults to now)
    ///   - period: The time step in seconds (defaults to 30); outside 1 to 300 the Rust core uses 30, and so does this
    /// - Returns: The number of seconds remaining
    public static func getRemainingSeconds(time: Date = Date(), period: Int = 30) -> Int {
        let step = (1...300).contains(period) ? period : 30
        let elapsed = Int(time.timeIntervalSince1970) % step
        return step - elapsed
    }
}
